#!/usr/bin/env node
// Writes web/src/workbench/core.gen.ts, the typed client the browser host uses to call the Go core
// (ADR-0045 §5), from the Wails bindings generated in packages/workbench/wailsjs/go (run by
// `task gen-wails`, hence by `task gen` and checked by `task check-gen`).
//
// Every binding becomes a typed method: `coreClient(core, ms).VaultAPI.OpenVault(path)` instead of
// `core.callWithin(ms, 'VaultAPI', 'OpenVault', path)`, so the host no longer writes service or method
// names by hand (ESLint refuses them outside the generated file). The generator fails, instead of
// skipping, on anything it does not recognise: a bound package other than `app`, a declaration it
// cannot parse, a .d.ts and a .js that disagree.
//
// Usage: node scripts/gen-core-client.mjs [--check]
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const wailsGo = join(root, 'packages/workbench/wailsjs/go');
const out = join(root, 'web/src/workbench/core.gen.ts');
const check = process.argv.includes('--check');

const fail = (msg) => {
  console.error(`gen-core-client: ${msg}`);
  process.exit(1);
};

if (!existsSync(join(wailsGo, 'models.ts')))
  fail(`${relative(root, wailsGo)} is missing: run \`task gen-wails\``);

for (const entry of readdirSync(wailsGo, { withFileTypes: true })) {
  if (entry.isDirectory() && entry.name !== 'app')
    fail(`bindings of package ${entry.name} are not handled: extend scripts/gen-core-client.mjs`);
}

const appDir = join(wailsGo, 'app');
for (const f of readdirSync(appDir)) {
  const base = f.replace(/\.(d\.ts|js)$/, '');
  if (base === f) fail(`unexpected file ${f} in ${relative(root, appDir)}`);
  if (!existsSync(join(appDir, `${base}.d.ts`)) || !existsSync(join(appDir, `${base}.js`)))
    fail(`${base}: the .d.ts and the .js must both exist`);
}
const DECL = /^export function (\w+)\(([^)]*)\):Promise<(.*)>;$/;
const IMPL = /^export function (\w+)\(([^)]*)\) \{$/;
const CALL = /^ {2}return window\['go'\]\['app'\]\['(\w+)'\]\['(\w+)'\]\(([^)]*)\);$/;
const IMPORT = /^import \{(\w+)\} from '\.\.\/models';$/;

// A type that names a model (`app.VaultInfo`, `Array<graph.Node>`) is used as plain data: the UI
// passes object literals and gets JSON back, never the generated classes.
const typeOf = (t) => (/\b[a-z]\w*\.[A-Z]/.test(t) ? `Data<${t}>` : t);
const param = (p) => {
  const i = p.indexOf(':');
  return `${p.slice(0, i)}: ${typeOf(p.slice(i + 1))}`;
};

const services = [];
const namespaces = new Set();
for (const file of readdirSync(appDir)
  .filter((f) => f.endsWith('.d.ts'))
  .sort()) {
  const service = file.slice(0, -'.d.ts'.length);
  const dts = readFileSync(join(appDir, file), 'utf8').split('\n');
  const methods = [];
  for (const line of dts) {
    if (line === '' || line.startsWith('//')) continue;
    const imp = IMPORT.exec(line);
    if (imp) {
      namespaces.add(imp[1]);
      continue;
    }
    const m = DECL.exec(line);
    if (!m) fail(`${service}: cannot parse ${JSON.stringify(line)}`);
    const [, name, params, result] = m;
    const args = params === '' ? [] : params.split(/,(?=arg\d+:)/);
    const names = args.map((a) => {
      const n = /^(arg\d+):/.exec(a);
      if (!n) fail(`${service}.${name}: cannot parse the parameter ${JSON.stringify(a)}`);
      return n[1];
    });
    methods.push({ name, params: args.map(param), names, result });
  }

  // The .js is what actually runs: it must call the same service and methods with the same arity.
  const js = readFileSync(join(appDir, `${service}.js`), 'utf8').split('\n');
  const impl = new Map();
  for (let i = 0; i < js.length; i++) {
    const m = IMPL.exec(js[i]);
    if (!m) continue;
    const c = CALL.exec(js[i + 1] ?? '');
    if (!c || c[1] !== service || c[2] !== m[1] || c[3] !== m[2])
      fail(`${service}.js: unexpected body for ${m[1]}`);
    impl.set(m[1], m[2] === '' ? 0 : m[2].split(',').length);
  }
  if (impl.size !== methods.length)
    fail(`${service}: ${methods.length} declarations, ${impl.size} implementations`);
  for (const m of methods)
    if (impl.get(m.name) !== m.names.length)
      fail(`${service}.${m.name}: the .d.ts and the .js disagree`);
  if (methods.length === 0) fail(`${service}: no method`);
  methods.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  services.push({ service, methods });
}
if (services.length === 0) fail('no binding found');

const ret = typeOf;
const lines = [];
const w = (s = '') => lines.push(s);
w(
  '// Code generated by `task gen` (scripts/gen-core-client.mjs) from the Wails bindings in packages/workbench/wailsjs/go.',
);
w('// DO NOT EDIT.');
w('//');
w(
  '// The typed client of the Go core for the browser host (ADR-0045 §5): one method per binding of',
);
w(
  '// App.Services(), with the parameter and result types of the bindings, called through the bridge',
);
w(
  '// with a time limit (`coreClient(core, ms)`; 0 = no limit). The host never writes a service or',
);
w(
  '// method name by hand: ESLint refuses them outside this file. A new binding appears here after',
);
w('// `task gen` (docs/desktop-web-sync.md, "Contratto degli eventi").');
w(
  `import type { ${[...namespaces].sort().join(', ')} } from '@memobrain/workbench/wailsjs/models';`,
);
w();
w(
  '/** A model of the bindings as plain data: the core answers with JSON, not with model classes. */',
);
w('export type Data<T> = T extends (...args: never[]) => unknown');
w('  ? never');
w('  : T extends readonly (infer U)[]');
w('    ? Data<U>[]');
w('    : T extends object');
w(
  '      ? { [K in keyof T as T[K] extends (...args: never[]) => unknown ? never : K]: Data<T[K]> }',
);
w('      : T;');
w();
w('/** What the client needs of the core: CoreHandle.callWithin (bridge.ts). */');
w('export interface CoreCaller {');
w('  callWithin<T = unknown>(');
w('    timeoutMs: number,');
w('    service: string,');
w('    method: string,');
w('    ...args: unknown[]');
w('  ): Promise<T>;');
w('}');
w();
w('/** Every binding of the core, by service. */');
w('export interface CoreClient {');
for (const { service, methods } of services) {
  w(`  readonly ${service}: {`);
  for (const m of methods) w(`    ${m.name}(${m.params.join(', ')}): Promise<${ret(m.result)}>;`);
  w('  };');
}
w('}');
w();
w('/** The services and methods of the bindings. */');
w('export const BINDINGS = {');
for (const { service, methods } of services)
  w(`  ${service}: [${methods.map((m) => `'${m.name}'`).join(', ')}],`);
w('} as const;');
w();
w('export type ServiceName = keyof typeof BINDINGS;');
w();
w('/**');
w(
  ' * The client of the core: calls that reject with a CoreTimeoutError when no answer arrives within',
);
w(
  " * `timeoutMs` (0: no limit), with a CoreDeadError when the core stopped, or with the binding's error.",
);
w(' */');
w('export function coreClient(core: CoreCaller, timeoutMs = 0): CoreClient {');
w('  const call = <T>(service: ServiceName, method: string, args: unknown[]): Promise<T> =>');
w('    core.callWithin<T>(timeoutMs, service, method, ...args);');
w('  return {');
for (const { service, methods } of services) {
  w(`    get ${service}(): CoreClient['${service}'] {`);
  w('      return {');
  for (const m of methods)
    w(
      `        ${m.name}: (${m.params.join(', ')}) => call('${service}', '${m.name}', [${m.names.join(', ')}]),`,
    );
  w('      };');
  w('    },');
}
w('  };');
w('}');
w();
w('type Hook<F> = F extends (...args: infer A) => Promise<infer R>');
w('  ? (args: A, result: R) => void');
w('  : never;');
w();
w('/**');
w(
  ' * Observers of the calls the UI makes through `window.go` (bridge.installWailsGlobals): called with',
);
w(' * the arguments and the result once a binding answered.');
w(' */');
w('export type BindingHooks = {');
w(
  '  -readonly [S in keyof CoreClient]?: { -readonly [M in keyof CoreClient[S]]?: Hook<CoreClient[S][M]> };',
);
w('};');
const text = `${lines.join('\n')}\n`;

const old = existsSync(out) ? readFileSync(out, 'utf8') : '';
if (old === text) process.exit(0);
if (check) fail(`${relative(root, out)} is out of date: run \`task gen\``);
writeFileSync(out, text);
console.log(`wrote ${relative(root, out)}`);
